using Microsoft.AspNetCore.Identity;
using System.ComponentModel.DataAnnotations.Schema;

namespace Library_Management_System.Models
{
    public class ApplicationUser : IdentityUser
    {
        // Generated by the database sequence
        // private set prevents accidental assignment; the sequence guarantees uniqueness.
        public int MembershipNumber { get; private set; }
        [NotMapped] //this will not mapped in the database 
        public string MembershipCode => $"LIB-{MembershipNumber:D6}";
        public DateTime CreatedAt { get; set; }
        public DateTime UpdatedAt { get; set; }
        public DateTime? DeletedAt { get; set; }
        public bool IsDeleted { get; set; } = false; //soft delete property to indicate if the user is deleted or not

        public ICollection<Loan> Loans { get; set; } // Navigation property for the loans associated with the user
    }
}